def quote_form(service=''):
    opts=['Στάμπες DTF με το μέτρο','Μπλουζάκια / επαγγελματική ένδυση','Κούπες / προσωποποιημένα δώρα','Διαφημιστικά είδη','Χονδρική συνεργασία']
    options='<option value="" disabled '+('selected' if not service else '')+'>Επιλέξτε υπηρεσία</option>'
    for o in opts: options += f'<option value="{esc(o)}" '+('selected' if o==service else '')+f'>{esc(o)}</option>'
    return f'''<form class="quote-form" id="quote" action="mailto:{CONTACT['email']}" method="post" enctype="text/plain" aria-label="Φόρμα προσφοράς"><div class="form-grid"><label>Ονοματεπώνυμο ή εταιρεία<input name="name" required autocomplete="name"></label><label>Τηλέφωνο ή email<input name="contact" required autocomplete="email"></label><label>Υπηρεσία<select name="service_select">{options}</select></label><label>Ποσότητα / μέτρα / τεμάχια<input name="quantity" placeholder="π.χ. 5 μέτρα DTF ή 30 μπλουζάκια"></label><label>Πότε το χρειάζεστε;<input name="deadline" placeholder="π.χ. μέχρι Παρασκευή ή δεν γνωρίζω"></label><label>Link αρχείου, αν υπάρχει<input name="file_link" placeholder="WeTransfer / Drive / Dropbox link"></label><label class="wide">Σχόλια<textarea name="message" rows="5" placeholder="Περιγράψτε σχέδιο, διαστάσεις, υλικό, χρώμα προϊόντος ή άλλη λεπτομέρεια."></textarea></label></div><p class="form-note">Με την υποβολή ανοίγει νέο email με τα στοιχεία της προσφοράς, ώστε να τα ελέγξετε πριν τα στείλετε στην Adapt Print.</p><button class="btn btn-primary" type="submit">Άνοιγμα email προσφοράς <span>→</span></button></form>'''
